create table `products` (`id` bigint unsigned not null auto_increment primary key, `category_id` bigint unsigned not null, `name` varchar(255) not null, `image` varchar(255) null, `slug` varchar(255) null, `description` text null, `stock` int null, `per_user_limit` int null, `sort` tinyint unsigned null, `allow_quantity` enum('disabled', 'separated', 'combined') not null default 'disabled', `server_id` bigint unsigned null, `email_template` text null, `created_at` timestamp null, `updated_at` timestamp null) default character set {{charset}} collate {{collation}};
alter table `products` add constraint `products_category_id_foreign` foreign key (`category_id`) references `categories` (`id`);
